```python
# Initialize an empty to-do list
to_do_list = []

def add_task():
    """Add a task to the to-do list."""
    task = input("Enter a task to add to the to-do list: ")
    if task:
        to_do_list.append(task)
        print(f"Task '{task}' added to the to-do list.")
    else:
        print("Task cannot be empty. Please try again.")

def remove_task():
    """Remove a task from the to-do list."""
    if to_do_list:
        task_index = int(input("Enter the index of the task to remove (1-based): ")) - 1
        if task_index < len(to_do_list):
            del to_do_list[task_index]
            print(f"Task at index {task_index + 1} removed from the to-do list.")
        else:
            print("Task not found. Please try again.")
    else:
        print("To-do list is empty. Nothing to remove.")

def list_tasks():
    """List all tasks in the to-do list."""
    if to_do_list:
        print("Your to-do list:")
        for i, task in enumerate(to_do_list, start=1):
            print(f"{i}. {task}")
    else:
        print("To-do list is empty. Nothing to show.")

def main():
    while True:
        print("\nAvailable commands:")
        print("add - Add a task to the to-do list")
        print("remove - Remove a task from the to-do list")
        print("list - List all tasks in the to-do list")
        print("quit - Exit the program")

        command = input("Enter a command: ").lower()

        if command == "add":
            add_task()
        elif command == "remove":
            remove_task()
        elif command == "list":
            list_tasks()
        elif command == "quit":
            print("Goodbye!")
            break
        else:
            print("Invalid command. Please try again.")

if __name__ == "__main__":
    main()
```

This program will allow the user to create and manage a to-do list using the provided commands. You can customize the prompts and error messages to fit your specific needs.
